/// Loads the Ogg Vorbis bytes for a built-in sound pack entry by [id], or
/// null if [id] doesn't match any entry in [kSpellSoundPack] (e.g. a spell
/// carrying a soundPackId from a pack version this build no longer ships --
/// callers should fall back to the elemental default, not crash).
Future<Uint8List?> loadPackSound(String id) async {
  for (final entry in kSpellSoundPack) {
    if (entry.id == id) {
      final data = await rootBundle.load(entry.asset);
      return data.buffer.asUint8List(data.offsetInBytes, data.lengthInBytes);
    }
  }
  return null;
}
